# EXPERIMENTAL. Examples of the gated 2-regime HMM: a real exercise recording and a PRCP recording (annotated tilt onsets and returns as dashed lines):
# heart rate, posterior probability of the non-reference regime, and the vagal-like and sympathetic-like states under M3 and under the HMM.  -> experiments/regimes/_out/figure.png
source("analysis/00_setup.R"); source("experiments/regimes/lib.R"); suppressMessages(library(ggplot2)); suppressMessages(library(patchwork)); ev_ann <- fread("data/prcp_events.csv")
panel_set <- function(dy, title, annot = NULL) { series <- prepare_series(dy); dy <- series$dy; tt <- cumsum(dy); base <- fit_ext(series); cp <- cp_search(series, base, min_gain = -Inf); h <- fit_regime(series, 2, cp, base, 7, 0.7); r <- h$run(); e <- state_estimates(base, FALSE)
  hr <- data.table(t = tt, y = 60 / dy, panel = "Heart rate (bpm)"); pw <- data.table(t = tt, y = rowSums(r$W[, -1, drop = FALSE]), panel = "P(non-reference regime)")
  st <- rbind(data.table(t = tt, y = e$xp, panel = "Vagal-like state (Hz)", model = "M3"), data.table(t = tt, y = r$X_p, panel = "Vagal-like state (Hz)", model = "HMM2"), data.table(t = tt, y = e$xs, panel = "Sympathetic-like state (Hz)", model = "M3"), data.table(t = tt, y = r$X_s, panel = "Sympathetic-like state (Hz)", model = "HMM2"))
  g <- function(d, nm) ggplot(d, aes(t, y)) + geom_line(linewidth = 0.4) + labs(title = nm, x = NULL, y = NULL) + theme_minimal(base_size = 9) + if (!is.null(annot)) geom_vline(xintercept = annot, linetype = "dashed", colour = "grey50", linewidth = 0.3)
  gs <- function(nm) ggplot(st[panel == nm], aes(t, y, colour = model)) + geom_line(linewidth = 0.4) + scale_colour_manual(values = c(M3 = "#b8860b", HMM2 = "#c1121f")) + labs(title = nm, x = "Time (s)", y = NULL, colour = NULL) + theme_minimal(base_size = 9) + theme(legend.position = "bottom") + if (!is.null(annot)) geom_vline(xintercept = annot, linetype = "dashed", colour = "grey50", linewidth = 0.3)
  (g(hr, paste0(title, ": heart rate")) / g(pw, "P(non-reference regime)") / gs("Vagal-like state (Hz)") / gs("Sympathetic-like state (Hz)")) + plot_layout(guides = "collect") & theme(legend.position = "bottom") }
d <- load_dataset("exercise", cfg); p1 <- panel_set(d$rr[["001"]], "Exercise 001")
dp <- load_dataset("prcp", cfg); id <- "12734"; off <- dp$rec[[id]]$time[1] - dp$rec[[id]]$rr[1]; a1 <- ev_ann[as.character(id) == "12734"]; ann <- c(a1$onset_s, a1$return_s[is.finite(a1$return_s)]) - off; p2 <- panel_set(dp$rr[[id]], "PRCP 12734 (dashed: annotated onsets and returns)", ann)
ggsave("experiments/regimes/_out/figure.png", p1 | p2, width = 13, height = 8.5, dpi = 150); cat("figure written\n")
